#include <stdio.h>

/* 招牌已经挂好（就当它是从招牌本上拼进来的） */
int fish_total(int bowl[], int count);

int main(void) {
    int count;
    if (scanf("%d", &count) != 1) {
        return 1;
    }
    int bowl[100];
    for (int i = 0; i < count; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }
    printf("整排合计 %d 条\n", fish_total(bowl, count));
    printf("头一只碗 %d 条\n", bowl[0]);
    return 0;
}

/* ===== 身子区：main 后面这块空地 ===== */
int fish_total(int bowl[], int count) {
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum = sum + bowl[i];
    }
    return sum;
}
